import brainmass, brainstate, braintools, brainunit as u
import jax.numpy as jnp
DT=.1*u.ms; CONN=jnp.array([[0.,0.,0.],[1.,0.,0.],[0.,1.,0.]])
class C(brainstate.nn.Module):
 def __init__(self):
  super().__init__(); self.node=brainmass.FitzHughNagumoStep(3,tau=20*u.ms,init_V=braintools.init.Constant(0*u.UNITLESS),init_w=braintools.init.Constant(0*u.UNITLESS)); self.h=brainstate.nn.Delay(jnp.zeros(3)*u.UNITLESS,time=12*u.ms,init=braintools.init.Constant(0*u.UNITLESS))
 def update(self,s,k,d):
  self.h.update(self.node.V.value); x=self.h.retrieve_at_step(jnp.rint(d/DT).astype(jnp.int32)); self.node(brainmass.additive_coupling(jnp.broadcast_to(x,CONN.shape),CONN,k)+s); return self.node.V.value

def run(k,d,size):
 with brainstate.environ.context(dt=DT):
  m=C();brainstate.nn.init_all_states(m)
  def step(i):
   stim=jnp.where((i>=20)&(i<30),1.,0.)*jnp.array([1.,0.,0.])*size
   with brainstate.environ.context(i=i,t=i*DT):return m(stim,k,d)
  return brainstate.transform.for_loop(step,jnp.arange(100))
r=brainstate.transform.vmap(run)(jnp.array([.2,.6])*u.UNITLESS,jnp.array([2.,6.])*u.ms,jnp.array([.8,.8])*u.UNITLESS)
print(type(r),r.shape,r.unit,r[:,-1])
PY"

